INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62800147', 62800147, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Komunikasi, Informatika dan Persandian', 'Jasa Perseorangan Kegiatan Lembaga Pemerintahan Bidang Komunikasi Dan Informatika 7', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 37440000, 'December 2025', 'APBD', 1, 1, '12 bulan', 'Melaksanakan peliputan langsung kegiatan Pemerintah Kota Yogyakarta, termasuk wawancara, observasi lapangan, dan pengumpulan informasi pendukung; menyusun dan menulis rilis berita, artikel, serta konten informatif lainnya sesuai kaidah jurnalistik dengan menjunjung tinggi etika profesi serta memastikan ketepatan waktu publikasi; mengunggah berita dan informasi pada website serta media sosial resmi Pemerintah Kota Yogyakarta; mengelola dan menata dokumentasi pendukung berupa foto dan materi liputan untuk kebutuhan publikasi; serta menyusun publikasi program dan kegiatan pemerintah dalam bentuk berita, artikel, feature, maupun naskah pendukung media lainnya.', 'Mampu menulis berita, artikel, dan laporan mendalam sesuai kaidah jurnalistik, termasuk penerapan 5W+1H, objektivitas, dan verifikasi fakta; mampu melakukan riset, wawancara, serta pengumpulan data secara akurat dan profesional; mampu mengoperasikan kamera foto dan video untuk mendukung kebutuhan peliputan lapangan; mampu mengoperasikan komputer dengan perangkat lunak pengolah naskah, grafis dasar, video dasar, serta aplikasi perkantoran; serta memahami etika jurnalistik dan mampu bekerja cepat di bawah tekanan tenggat waktu.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 90178);
