INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62800297', 62800297, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Komunikasi, Informatika dan Persandian', 'Jasa Perseorangan Kegiatan Lembaga Pemerintahan Bidang Komunikasi Dan Informatika 1', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 39084000, 'December 2025', 'APBD', 1, 1, '12 bulan', 'Melaksanakan peliputan dan pendokumentasian kegiatan Pemerintah Kota Yogyakarta dalam bentuk video dan foto; melakukan pengambilan gambar, pengelolaan audio, serta penyusunan materi visual sesuai kebutuhan publikasi; melaksanakan proses penyuntingan video untuk menghasilkan konten audiovisual yang informatif, komunikatif, dan sesuai standar publikasi Pemerintah Kota Yogyakarta; mengelola, menyimpan, dan menata arsip dokumentasi video dan foto; membuat materi publikasi program dan kegiatan dalam bentuk konten audiovisual untuk dipublikasikan melalui website, media sosial, dan kanal resmi lainnya; serta berkoordinasi dengan tim terkait dalam proses pra-produksi, produksi, dan pasca-produksi konten video.', 'Mampu mengoperasikan kamera video, DSLR/mirrorless, serta peralatan pendukung seperti gimbal, lighting, dan audio recorder; menguasai teknik pengambilan gambar termasuk framing, angle, dan movement serta dasar-dasar sinematografi; mampu melakukan proses editing video menggunakan perangkat lunak seperti Adobe Premiere Pro, CapCut, Final Cut Pro, atau setara; mampu mengoperasikan komputer dengan perangkat lunak pengolah video, grafis pendukung, dan aplikasi perkantoran; memahami alur produksi video dari pra-produksi, produksi, hingga pasca-produksi; serta memiliki kemampuan storytelling visual untuk menghasilkan konten yang menarik dan komunikatif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 90210);
