INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62800184', 62800184, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Komunikasi, Informatika dan Persandian', 'Jasa Perseorangan Kegiatan Lembaga Pemerintahan Bidang Komunikasi Dan Informatika 4', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 39084000, 'December 2025', 'APBD', 1, 1, '12 bulan', 'Melakukan pemahaman terhadap isu, data, dan informasi terkait program serta kegiatan Pemerintah Kota Yogyakarta sebagai dasar perancangan materi grafis; mengolah informasi hasil peliputan atau data yang diberikan menjadi desain visual yang informatif, kreatif, dan sesuai identitas serta standar branding Pemerintah Kota Yogyakarta; membuat berbagai materi publikasi grafis seperti poster, spanduk, banner, infografis, ilustrasi, dan konten visual lainnya untuk mendukung penyebaran informasi; menyusun desain grafis sesuai kaidah komunikasi visual dengan menjaga konsistensi desain serta memastikan ketepatan waktu produksi; menyiapkan materi grafis untuk dipublikasikan pada website, media sosial, dan kanal resmi pemerintah; mengelola, menata, serta mengarsipkan file desain dan aset visual untuk kebutuhan dokumentasi dan publikasi berkelanjutan; menggunakan perangkat lunak desain grafis seperti Adobe Illustrator, Adobe Photoshop, Adobe InDesign, atau software setara secara terampil untuk menghasilkan materi visual yang berkualitas; serta menyusun materi pendukung publikasi program dan kegiatan pemerintah dalam bentuk grafis yang dapat digunakan bersama media berita maupun audiovisual.', 'Mampu menghasilkan ilustrasi dan desain grafis sesuai brief dengan gaya yang konsisten dan estetis; menguasai prinsip dasar desain seperti tipografi, layout, warna, dan komposisi serta ilustrasi digital; mampu mengoperasikan komputer dengan perangkat lunak pengolah grafis seperti Adobe Photoshop, Illustrator, atau setara, serta memahami dasar pengolahan video dan aplikasi perkantoran; serta memiliki kemampuan visual storytelling sehingga dapat menerjemahkan konsep menjadi aset visual yang jelas, menarik, dan komunikatif.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 93738);
