INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63040407', 63040407, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Belanja Pengembangan Portal Layanan Teknologi Informasi dan Komunikasi (Programmer)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 139150000, 'January 2026', 'APBD', 1, 1, '11 Bulan', '1) Mempelajari konsep rancangan dan spesifikasi program, sesuai spesifikasi program yang telah dibuat oleh Tim Teknis Dinas Komunikasi, Informatika dan Statistik Provinsi DKI Jakarta 2) Membuat modul-modul pemrograman yang terstruktur sesuai konsep rancangan dan spesifikasi program aplikasi yang dibuat serta menggunakan framework yang telah disepakati dengan Tim Teknis Dinas Komunikasi, Informatika dan Statistik Provinsi DKI Jakarta 3) Melakukan pembuatan prosedur pada database 4) Melakukan penyuntingan kode sumber dan/atau pengubahan script atau kode sumber meliputi proses pengetesan, analisis, pembetulan kesalahan, pengoptimasian algoritma dan normalisasi kode 5) Melakukan riset dan pengembangan keamanan Portal layanan 6) Melakukan instalasi aplikasi pada server yang telah disediakan 7) Membuat prosedur teknis yang dibutuhkan dalam pembuatan dan pengembangan sistem informasi 8) Melakukan Unit Test, Integration Test, serta mendampingi User Acceptance Test setelah modul-modul dalam aplikasi dapat digunakan, bersama Tim Teknis Diskominfotik Provinsi DKI Jakarta 9) Melakukan pemeliharaan aplikasi / sistem informasi dan memastikan aplikasi bekerja dengan optimal 10) Melakukan pendampingan dan pelatihan kepada Tim Teknis Diskominfotik Provinsi DKI Jakarta 11) Membuat laporan bulanan berupa dokumen teknis atas hasil pengembangan modul aplikasi yang telah berjalan serta perbaikan program yang telah dilakukan selama pelaksanaan pekerjaan', '• S1 Teknik Informatika • Pengalaman sebagai Programmer paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak • Memiliki sertifikat pelatihan pemprograman PHP (framework laravel), HTML & CSS, JavaScript (framework vue.js); • Memiliki sertifikat pelatihan integrasi aplikasi webservice/RESTful API;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 95245);
