INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62782746', 62782746, 'analyze_legacy', 'Kab. Halmahera Tengah', 'kabkota', 'Kecamatan Patani Utara', 'Peralatan Studio Video dan Film', 'Barang', 'Pengadaan Langsung', 'Maluku Utara, Halmahera Tengah (Kab.)', 22811050, 'January 2026', 'APBD', 1, 1, '1 Buah', 'Peralatan Studio Video dan Film;', 'Belanja DroneZona 1 Zona 3;', 22811050, 'high', 'Pengadaan peralatan studio video/film berupa drone oleh unit kecamatan terindikasi kurang selaras dengan fungsi layanan dasar administratif kewilayahan. Dari judul dan spesifikasi, item ini tampak lebih bersifat penunjang khusus daripada kebutuhan utama pemerintahan kecamatan, sehingga seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 99702);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63385046', 63385046, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA MUSEUM KESEJARAHAN JAKARTA', 'Penyediaan jasa perizinan KDO/KDO khusus', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 15073100, 'June 2026', 'APBD', 1, 1, '5 Motor dan 4 Mobil', 'Pekerjaan ini meliputi penyediaan jasa pengurusan dan pembayaran pajak, bea, serta perizinan Kendaraan Dinas Operasional (KDO) dan KDO Khusus berupa mobil dan sepeda motor, guna menjamin legalitas operasional kendaraan dalam mendukung pelaksanaan tugas kedinasan. Kegiatan dilaksanakan sesuai ketentuan peraturan perundang-undangan yang berlaku, meliputi pengurusan dokumen administrasi kendaraan dan pembayaran kewajiban yang melekat pada kepemilikan serta penggunaan kendaraan dinas.', 'Spesifikasi pekerjaan mencakup penyediaan jasa perizinan untuk 4 (empat) unit mobil dinas dan 5 (lima) unit sepeda motor dinas, yang meliputi pembayaran Pajak Kendaraan Bermotor (PKB), Bea Balik Nama Kendaraan Bermotor (apabila diperlukan), penerbitan dan/atau perpanjangan Surat Tanda Nomor Kendaraan (STNK), pengesahan dokumen kendaraan, serta pengurusan perizinan lain yang dipersyaratkan sesuai ketentuan yang berlaku. Seluruh proses dilaksanakan secara tepat waktu, akuntabel, dan terdokumentasi, dengan bukti pembayaran dan dokumen perizinan yang sah sebagai pertanggungjawaban keuangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 99703);
